def calculate_pair_probability(n):
    if n > 365:
        return 1.0
    prob_no_shared = 1.0
    for i in range(n):
        prob_no_shared *= (365 - i) / 365
    return 1 - prob_no_shared


def calculate_triple_probability(n):
    if n > 365:
        return 1.0
    prob_at_most_two = 1.0
    for i in range(n):
        prob_at_most_two *= (365 - i) / 365
    prob_exactly_two = 0.0
    for i in range(n):
        prob_exactly_two += (365 - i) / 365 * (i / 365) * (i - 1) / 365
    return 1 - (prob_at_most_two + prob_exactly_two)

